SELECT DATE_FORMAT(rslt_date, '%Y-%m-%d') AS dtStats, msg_type AS serviceType, COUNT(*) AS inCnt, SUM(CASE WHEN rslt_val = '0' OR rslt_val = '1000' THEN 1 ELSE 0 END) AS succCnt, SUM(CASE WHEN rslt_val IN ('9999', '-1') THEN 1 ELSE 0 END) AS errorCnt, SUM(CASE WHEN rslt_val NOT IN ('0', '1000', '9999', '-1', '') AND rslt_val IS NOT NULL THEN 1 ELSE 0 END) AS failCnt, SUM(CASE WHEN rslt_val = '' OR rslt_val IS NULL THEN 1 ELSE 0 END) AS waitCnt, 0 AS ingCnt FROM ${tableName} WHERE 1=1
AND user_id = #{userId}
AND msg_type = #{serviceType}
AND rslt_date >= #{startDate}
AND rslt_date <= #{endDate}
GROUP BY DATE_FORMAT(rslt_date, '%Y-%m-%d'), msg_type ORDER BY dtStats DESC, serviceType

SELECT user_id AS userId, msg_type AS serviceType, COUNT(*) AS totalCnt, SUM(CASE WHEN rslt_val = '0' OR rslt_val = '1000' THEN 1 ELSE 0 END) AS succCnt, SUM(CASE WHEN rslt_val NOT IN ('0', '1000') OR rslt_val IS NULL THEN 1 ELSE 0 END) AS failCnt FROM ${tableName} WHERE 1=1
AND user_id IN
#{userId}
AND rslt_date >= #{startDate}
AND rslt_date <= #{endDate}
GROUP BY user_id, msg_type ORDER BY user_id, msg_type

SELECT CASE msg_type WHEN 'SMS' THEN 'SMS' WHEN 'LMS' THEN 'LMS' WHEN 'MMS' THEN 'MMS' WHEN 'ATA' THEN '알림톡' WHEN 'FTA' THEN '친구톡' WHEN 'FTI' THEN '친구톡(이미지)' ELSE msg_type END AS serviceTypeName, '발송' AS category, COUNT(*) AS count, NULL AS unitPrice, NULL AS amount, '' AS remarks FROM ${tableName} WHERE rslt_val IN ('0', '1000')
AND user_id = #{userId}
AND rslt_date >= #{startDate}
AND rslt_date <= #{endDate}
GROUP BY msg_type ORDER BY msg_type

SELECT
    COUNT(*) AS totalCnt,
    SUM(CASE WHEN rslt_val = '0' OR rslt_val = '1000' THEN 1 ELSE 0 END) AS succCnt,
    SUM(CASE WHEN rslt_val NOT IN ('0', '1000') OR rslt_val IS NULL THEN 1 ELSE 0 END) AS failCnt
FROM ${tableName}


        user_id = #{userId}
